-- Variants of issues/008 on the sample database (scripts/setup_mariadb.sh): the left arm
-- A, the right arm B UNION ALL C, their INTERSECT ALL with and without a derived table.
USE test;
SELECT 'A rows with k0 = 8811', COUNT(*) FROM (SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON t1b.c1 <= 5000 WHERE t1b.c1 >= 1000) AS a WHERE a.k0 = 8811;
SELECT 'B UNION ALL C rows with k0 = 8811', COUNT(*) FROM ((SELECT t2b.c2 AS k0, t2b.c2 AS k1, t3a.c1 AS k2 FROM t3 AS t3a INNER JOIN t2 AS t2b ON (t2b.c2 = 5) AND (t3a.c7 > 5000) WHERE ((t3a.c3 < t2b.c2) OR (t2b.c2 = 1)) OR (EXISTS (SELECT t2s87.c1 FROM t2 AS t2s87 WHERE t2s87.c2 >= t2s87.c2))) UNION ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (t1a.c4 IS NULL) AND (t1a.c4 = 20) WHERE ((t1b.c4 >= t1a.c4) OR (t1b.c4 IS NULL)) OR (t1a.c4 <> 20))) AS bc WHERE bc.k0 = 8811;
SELECT '1 original', 'rows:';
(SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON t1b.c1 <= 5000 WHERE t1b.c1 >= 1000) INTERSECT ALL ((SELECT t2b.c2 AS k0, t2b.c2 AS k1, t3a.c1 AS k2 FROM t3 AS t3a INNER JOIN t2 AS t2b ON (t2b.c2 = 5) AND (t3a.c7 > 5000) WHERE ((t3a.c3 < t2b.c2) OR (t2b.c2 = 1)) OR (EXISTS (SELECT t2s87.c1 FROM t2 AS t2s87 WHERE t2s87.c2 >= t2s87.c2))) UNION ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (t1a.c4 IS NULL) AND (t1a.c4 = 20) WHERE ((t1b.c4 >= t1a.c4) OR (t1b.c4 IS NULL)) OR (t1a.c4 <> 20)));
SELECT '2 mutant: SELECT DISTINCT * FROM (... INTERSECT ALL ...)', 'rows:';
SELECT DISTINCT * FROM ((SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON t1b.c1 <= 5000 WHERE t1b.c1 >= 1000) INTERSECT ALL ((SELECT t2b.c2 AS k0, t2b.c2 AS k1, t3a.c1 AS k2 FROM t3 AS t3a INNER JOIN t2 AS t2b ON (t2b.c2 = 5) AND (t3a.c7 > 5000) WHERE ((t3a.c3 < t2b.c2) OR (t2b.c2 = 1)) OR (EXISTS (SELECT t2s87.c1 FROM t2 AS t2s87 WHERE t2s87.c2 >= t2s87.c2))) UNION ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (t1a.c4 IS NULL) AND (t1a.c4 = 20) WHERE ((t1b.c4 >= t1a.c4) OR (t1b.c4 IS NULL)) OR (t1a.c4 <> 20)))) AS vs_d1;
SELECT '3 SELECT * FROM (... INTERSECT ALL ...)', COUNT(*) FROM ((SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON t1b.c1 <= 5000 WHERE t1b.c1 >= 1000) INTERSECT ALL ((SELECT t2b.c2 AS k0, t2b.c2 AS k1, t3a.c1 AS k2 FROM t3 AS t3a INNER JOIN t2 AS t2b ON (t2b.c2 = 5) AND (t3a.c7 > 5000) WHERE ((t3a.c3 < t2b.c2) OR (t2b.c2 = 1)) OR (EXISTS (SELECT t2s87.c1 FROM t2 AS t2s87 WHERE t2s87.c2 >= t2s87.c2))) UNION ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (t1a.c4 IS NULL) AND (t1a.c4 = 20) WHERE ((t1b.c4 >= t1a.c4) OR (t1b.c4 IS NULL)) OR (t1a.c4 <> 20)))) AS x;
SELECT '4 SELECT DISTINCT * FROM (... INTERSECT ...)', COUNT(*) FROM (SELECT DISTINCT * FROM ((SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON t1b.c1 <= 5000 WHERE t1b.c1 >= 1000) INTERSECT ((SELECT t2b.c2 AS k0, t2b.c2 AS k1, t3a.c1 AS k2 FROM t3 AS t3a INNER JOIN t2 AS t2b ON (t2b.c2 = 5) AND (t3a.c7 > 5000) WHERE ((t3a.c3 < t2b.c2) OR (t2b.c2 = 1)) OR (EXISTS (SELECT t2s87.c1 FROM t2 AS t2s87 WHERE t2s87.c2 >= t2s87.c2))) UNION ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (t1a.c4 IS NULL) AND (t1a.c4 = 20) WHERE ((t1b.c4 >= t1a.c4) OR (t1b.c4 IS NULL)) OR (t1a.c4 <> 20)))) AS y) AS x;
SELECT '5 INTERSECT ALL with a derived right arm', COUNT(*) FROM ((SELECT t2a.c2 AS k0, t1b.c4 AS k1, t2a.c1 AS k2 FROM t2 AS t2a LEFT JOIN t1 AS t1b ON t1b.c1 <= 5000 WHERE t1b.c1 >= 1000) INTERSECT ALL (SELECT * FROM ((SELECT t2b.c2 AS k0, t2b.c2 AS k1, t3a.c1 AS k2 FROM t3 AS t3a INNER JOIN t2 AS t2b ON (t2b.c2 = 5) AND (t3a.c7 > 5000) WHERE ((t3a.c3 < t2b.c2) OR (t2b.c2 = 1)) OR (EXISTS (SELECT t2s87.c1 FROM t2 AS t2s87 WHERE t2s87.c2 >= t2s87.c2))) UNION ALL (SELECT t1b.c1 AS k0, t1a.c4 AS k1, t1b.c4 AS k2 FROM t1 AS t1a LEFT JOIN t1 AS t1b ON (t1a.c4 IS NULL) AND (t1a.c4 = 20) WHERE ((t1b.c4 >= t1a.c4) OR (t1b.c4 IS NULL)) OR (t1a.c4 <> 20))) AS bc)) AS x;
